if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'read_print_settings',description:'Read current design dimensions and processing settings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({filename:name,sourcePixels:[sourceW,sourceH],settings:params(),outputPixels:dims(validate(params()))})},{name:'configure_print_settings',description:'Set print dimensions and image processing options. Does not download a file.',inputSchema:{type:'object',properties:{widthCm:{type:'number',minimum:.5,maximum:100},dpi:{type:'number',enum:[150,300,600]},removeOn:{type:'boolean'},removeColor:{type:'string',pattern:'^#[0-9a-fA-F]{6}$'},halftoneOn:{type:'boolean'},shape:{type:'string',enum:['circle','square','diamond','line']},coverage:{type:'number',minimum:5,maximum:100},lpi:{type:'number',minimum:5,maximum:80},dualHalftone:{type:'boolean'},lpi2:{type:'number',minimum:5,maximum:80},angle2:{type:'number',minimum:0,maximum:180}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Settings object required.');const allowed=['widthCm','dpi','removeOn','removeColor','halftoneOn','shape','coverage','lpi','dualHalftone','lpi2','angle2'];for(const k of Object.keys(input)){if(!allowed.includes(k))throw Error('Unknown setting: '+k);if(typeof input[k]!==typeof defaults[k])throw Error('Wrong type: '+k);}const p=validate({...params(),...input});write(p);historyCommit();sizeInfo();await new Promise(resolve=>{render();const check=setInterval(()=>{if(!previewWorker){clearInterval(check);resolve();}},30);});return {settings:params(),outputPixels:dims(p)};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}}
registerStudioModule({id:initialTool==='recolor'?'recolor':initialTool==='remove'?'remove':'editor',onFit:()=>{fitView=true;layout();},getComparison:()=>[previewSource,result],getDraft:()=>source?{images:{source},data:{name}}:null,restoreDraft:async d=>{const restoredSettings=Object.fromEntries(keys.map(k=>[k,numbers.has(k)?Number(d.settings[k]):d.settings[k]]));await upload(new File([d.images.source],d.data.name,{type:'image/png'}),restoredSettings);},afterRestore:()=>{committed=params();schedule();},onZoom:factor=>{if(!previewSource)return;fitView=false;zoom=Math.max(.03,Math.min(4,zoom*factor));layout();},getExportInfo:()=>source?{widthCm:params().widthCm,dpi:params().dpi,aspect:sourceW/sourceH}:null,exportAtSize:async(size,onProgress)=>{requireTransferImage(source,exporting||loading||aiRunning);const p=validate({...params(),widthCm:size.widthCm,dpi:size.dpi}),d=outputDimensions(size.widthCm,size.dpi,sourceW/sourceH);exporting=true;sizeInfo();try{return await processedArtifact({source,...d,params:p,name:name.replace(/\\.[^.]+$/,'')+'_LZ.png',onProgress});}finally{exporting=false;sizeInfo();}},exportCurrent:async onProgress=>{requireTransferImage(source,exporting||loading||aiRunning);const p=validate(params()),d=dims(p);exporting=true;sizeInfo();try{return await processedArtifact({source,...d,dpi:p.dpi,params:p,name:name.replace(/\\.[^.]+$/,'')+'_LZ_editor.png',onProgress})}finally{exporting=false;sizeInfo()}},importCurrent:async(blob,filename,meta)=>upload(new File([blob],filename,{type:blob.type}),{...defaults,widthCm:meta.widthCm,dpi:meta.dpi})});
import {imagePrintSize} from './image-print-size.js';
for(const button of document.querySelectorAll('[data-min-dot],[data-min-hole]'))button.addEventListener('click',()=>{const field=button.dataset.minDot!==undefined?'minDotMm':'minHoleMm';$(field).value=button.dataset.minDot??button.dataset.minHole;$(field).dispatchEvent(new Event('input'));$(field).dispatchEvent(new Event('change'));});
