let assemblyFrame=0,assemblyClock=null;
const motionAllowed=()=>!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const animationPrefs=readStorage('lzbox-animation',{});
$('assemblySpeed').value=String([1,2,3].includes(Number(animationPrefs?.speed))?Number(animationPrefs.speed):2);
$('autoAssembly').checked=typeof animationPrefs?.auto==='boolean'?animationPrefs.auto:motionAllowed();
function saveAnimationPrefs(){putStorage('lzbox-animation',{speed:Number($('assemblySpeed').value),auto:$('autoAssembly').checked});}
$('autoAssembly').onchange=saveAnimationPrefs;
function showAssemblyProgress(){
 const progress=assemblyClock?.progress??1,phase=assemblyPhase(progress,panels.length),step=renderer.assemblyPlan[phase.index],label=phase.progress>=1?'Revisando ensamble':(phase.index+1)+' / '+panels.length+' \xB7 '+step.label;
 const status=assemblyClock?.paused?'Pausa \xB7 '+label:label;if($('assemblyStatus').textContent!==status)$('assemblyStatus').textContent=status;
 $('assemblyProgress').value=Math.round(progress*100);$('playAssembly').textContent=assemblyClock?.paused?'\u25B6 Continuar':'\u2161 Pausar';
}
