 if(assemblyClock){if(assemblyClock.paused){assemblyClock.resume(performance.now());$('playAssembly').setAttribute('aria-label','Pausar animaci\xF3n de armado');assemblyFrame=requestAnimationFrame(assemblyTick);}else{assemblyClock.pause(performance.now());cancelAnimationFrame(assemblyFrame);assemblyFrame=0;renderer.assembly=assemblyClock.progress;renderer.draw();$('playAssembly').setAttribute('aria-label','Continuar animaci\xF3n de armado');}showAssemblyProgress();return;}
 if(!valid)return;setView('3d');renderer.opening=0;state.opening=0;$('opening').value=0;$('openingValue').textContent='0%';renderer.explode=0;$('explode').value=0;
 // Explicit playback and the user's auto-animation choice override the OS
 // preference; reduced motion only sets the initial automatic-playback default.
