   if(registrationFingerprint&&registrationFingerprint!==currentFingerprint)clearRegistration('El dise\xF1o cambi\xF3; vuelve a registrar las referencias.');
   if(registrationSession&&registrationSession!==machine?.sessionId)clearRegistration('Cambi\xF3 la sesi\xF3n USB; vuelve a registrar las referencias.');
