 const live=button('M\xE1quina desconectada',()=>show('operate'),'workshop-live');nav.append(live);document.querySelector('.topbar').after(nav);
 const operator=el('section','workshop-operator');operator.id='workshopOperator';operator.hidden=true;root.after(operator);
