 const dock=el('aside','workshop-prepare-dock');dock.hidden=true;config.after(dock);
 dock.innerHTML='<div class="panel-head"><h2>Material y distribuci\xF3n</h2></div><p class="hint">Las coordenadas de piezas pertenecen a la hoja. El origen f\xEDsico se elige en Operar m\xE1quina.</p><div id="workshopCutSettings"></div><div class="workshop-piece-properties"><h3>Pieza seleccionada</h3><p id="workshopPieceName">Selecciona una pieza en el plano.</p><label>X \xB7 mm<input id="workshopPieceX" type="number" step="0.1"></label><label>Y \xB7 mm<input id="workshopPieceY" type="number" step="0.1"></label><p id="workshopPieceSize" class="hint"></p><button id="workshopApplyPosition" class="btn outline" type="button">Aplicar posici\xF3n</button><button id="workshopRotatePiece" class="btn outline" type="button">Girar 90\xB0</button></div><div id="workshopPrepareExport"></div>';
 const planTools=$('planTools');if(planTools)document.querySelector('.viewer-body')?.before(planTools);
