 const bedLabel=el('p','workshop-bed-label','Cama: se obtiene al conectar la m\xE1quina. Material: tama\xF1o de hoja configurado.');$('workshopCutSettings').prepend(bedLabel);
 const presetLabel=document.querySelector('label[for=sheetPreset]');if(presetLabel)presetLabel.textContent='Tama\xF1o del material / hoja';
 const exportCopy=document.querySelector('.export-copy');if(exportCopy)exportCopy.hidden=true;
 const exportPanel=document.querySelector('.export-panel');if(exportPanel)$('workshopPrepareExport').append(exportPanel);
 const catalog=el('dialog','workshop-catalog');catalog.setAttribute('aria-labelledby','workshopCatalogTitle');
 catalog.innerHTML='<div class="dialog-header"><div><span class="eyebrow">CAT\xC1LOGO DEL TALLER</span><h2 id="workshopCatalogTitle">Elige un modelo</h2></div></div>';
