 const widthLabel=el('label','','Panel');const width=el('input');width.type='range';width.min='320';width.max='480';width.step='10';width.value=String(preferences.width||360);width.setAttribute('aria-label','Ancho del panel de propiedades');width.oninput=()=>{preferences.width=Number(width.value);saveLayout();applyLayout();};widthLabel.append(width);
 tools.append(collapse,widthLabel,button('Restaurar distribuci\xF3n',()=>{preferences.width=360;preferences.collapsed=false;width.value='360';saveLayout();applyLayout();},'btn quiet'));nav.after(tools);
 const globalMachine=el('div','workshop-machine-strip');globalMachine.hidden=true;globalMachine.innerHTML='<span id="workshopMachineMessage"></span>';
